def _apply(s,changes,label):
    for i,(old,new) in enumerate(changes):
        count=s.count(old)
        if count!=1:
            raise AssertionError(f"{label} change {i} expected one old anchor, found {count}")
        s=s.replace(old,new,1)
    return s

def patch_main(s):
    return _apply(s,MAIN_CHANGES,"main")

def patch_crew(s):
    return _apply(s,CREW_CHANGES,"crew")
